/**
 * Tool Dispatcher: every ork PreToolUse handler in one process.
 *
 * yellow-refactor M1, phase 1. Shipped hooks.json starts 3 PreToolUse
 * processes for Bash, Write, Edit and Read (the per-tool sync dispatcher plus
 * lifecycle/webhook-forwarder twice, once from the per-tool group and once
 * from the matcher-less group). This handler replaces all of them with one
 * matcher-less entry: it routes by tool_name to the same handlers, in the
 * same order, and forwards the event exactly once.
 *
 * OFF by default. It is wired only into the hooks.json variant written by
 * scripts/unified-pretool-hooks.mjs; the shipped hooks.json never names it.
 *
 * Contract:
 * - The route's primary (sync) handler result is returned unchanged, so a
 *   deny, ask, defer or updatedInput reaches CC exactly as today.
 * - Observers (today registered async) run after the primary handler; their
 *   results are ignored and a throw never changes the verdict.
 * - The webhook forward runs last and is isolated the same way.
 * - Every handler runs within its hooks.json timeout (lib/budget.ts); one
 *   over budget is abandoned, so a hung observer or forwarder cannot hold
 *   the primary's verdict; a primary over budget denies (fail closed).
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { ProofLog, proofBreaks, proofBreakError, proofEnabled, type ProofEnv } from '../lib/dispatch-proof.js';
import { syncBashDispatcher } from './bash/sync-bash-dispatcher.js';
import { syncWriteEditDispatcher } from './write-edit/sync-write-edit-dispatcher.js';
import { tldrSummary } from './read/tldr-summary.js';
import { syncTaskDispatcher } from './task/sync-task-dispatcher.js';
import { routeObserver } from './task/route-observer.js';
import { skillTracker } from './skill/skill-tracker.js';
import { context7Tracker } from './mcp/context7-tracker.js';
import { memoryValidator } from './mcp/memory-validator.js';
import headlessResponder from './ask/headless-responder.js';
import { workflowAgentTypeAdvisor } from './task/workflow-agenttype-advisor.js';
import { webhookForwarder } from '../lifecycle/webhook-forwarder.js';
import { ccMatcherMatches } from '../lib/cc-matcher.js';
import { TIMED_OUT, withBudget } from '../lib/budget.js';

const HOOK_NAME = 'tool-dispatcher';

type Fn = (input: HookInput, ctx: HookContext) => HookResult | Promise<HookResult>;

interface Route {
  /** True when this route owns the tool. */
  match: (tool: string) => boolean;
  /** Handler ids as named in hooks.json, primary first (for the coverage test). */
  handlers: string[];
  /** Sync handler whose result is the hook result; absent for observe-only routes. */
  primary?: Fn;
  /** Handlers that were async in hooks.json: run after, result ignored. */
  observers: Fn[];
}

/** A route matches exactly as CC reads the shipped group's matcher. */
const cc = (matcher: string) => (tool: string) => ccMatcherMatches(matcher, tool);

/**
 * Mirrors the PreToolUse groups of src/hooks/hooks.json (2026-10-31); each
 * route carries its group's matcher verbatim (asserted by test).
 */
export const PRETOOL_ROUTES: Route[] = [
  { match: cc('Bash'), handlers: ['pretool/bash/sync-bash-dispatcher'], primary: syncBashDispatcher, observers: [] },
  {
    match: cc('Write|Edit'),
    handlers: ['pretool/write-edit/sync-write-edit-dispatcher'],
    primary: syncWriteEditDispatcher,
    observers: [],
  },
  { match: cc('Read'), handlers: ['pretool/read/tldr-summary'], primary: tldrSummary, observers: [] },
  {
    match: cc('Agent'),
    handlers: ['pretool/task/sync-task-dispatcher', 'pretool/task/route-observer'],
    primary: syncTaskDispatcher,
    observers: [routeObserver],
  },
  { match: cc('Skill'), handlers: ['pretool/skill/skill-tracker'], observers: [skillTracker] },
  { match: cc('mcp__context7__*'), handlers: ['pretool/mcp/context7-tracker'], primary: context7Tracker, observers: [] },
  { match: cc('mcp__memory__*'), handlers: ['pretool/mcp/memory-validator'], primary: memoryValidator, observers: [] },
  { match: cc('AskUserQuestion'), handlers: ['pretool/ask/headless-responder'], primary: headlessResponder, observers: [] },
  {
    match: cc('Workflow'),
    handlers: ['pretool/task/workflow-agenttype-advisor'],
    primary: workflowAgentTypeAdvisor,
    observers: [],
  },
];

/** hooks.json timeout per PreToolUse handler, in seconds: its budget (asserted by test). */
export const PRETOOL_TIMEOUTS_S: Record<string, number> = {
  'pretool/bash/sync-bash-dispatcher': 15,
  'lifecycle/webhook-forwarder': 15,
  'pretool/write-edit/sync-write-edit-dispatcher': 15,
  'pretool/skill/skill-tracker': 5,
  'pretool/mcp/context7-tracker': 10,
  'pretool/mcp/memory-validator': 10,
  'pretool/task/sync-task-dispatcher': 15,
  'pretool/task/route-observer': 5,
  'pretool/read/tldr-summary': 15,
  'pretool/ask/headless-responder': 5,
  'pretool/task/workflow-agenttype-advisor': 10,
};

/** Whole-run budget, under the variant's fixed entry timeout (PRETOOL_ENTRY_TIMEOUT_S). */
export const PRETOOL_RUN_BUDGET_MS = 50_000;

export interface DispatchOptions {
  /** Budget for a handler id, in ms. Defaults to its hooks.json timeout. */
  budgetMs?: (id: string) => number;
}

const defaultBudget = (id: string) => (PRETOOL_TIMEOUTS_S[id] ?? 15) * 1000;

async function isolated(
  name: string,
  fn: Fn,
  input: HookInput,
  ctx: HookContext,
  env: ProofEnv,
  proof: ProofLog,
  budget: number,
): Promise<void> {
  try {
    const r = await withBudget(() => {
      if (proofBreaks(env, name)) throw proofBreakError(name);
      return fn(input, ctx);
    }, budget);
    if (r === TIMED_OUT) {
      ctx.log(HOOK_NAME, `${name} over its ${budget} ms budget (abandoned)`);
      proof.record(name, 'failed');
      return;
    }
    proof.record(name, 'ok');
  } catch (err) {
    ctx.log(HOOK_NAME, `${name} failed (isolated): ${err instanceof Error ? err.message : String(err)}`);
    proof.record(name, 'failed');
  }
}

/**
 * `env` is injectable for tests; it only drives the dispatch proof
 * (lib/dispatch-proof.ts). With proof mode off, a throw from the primary
 * handler propagates exactly as it did from its own process.
 */
export async function toolDispatcher(
  input: HookInput,
  ctx: HookContext = NOOP_CTX,
  env: ProofEnv = process.env,
  opts: DispatchOptions = {},
): Promise<HookResult> {
  const tool = input.tool_name ?? '';
  const route = PRETOOL_ROUTES.find((r) => r.match(tool));
  const budgetOf = opts.budgetMs ?? defaultBudget;
  const deadline = Date.now() + PRETOOL_RUN_BUDGET_MS;
  const left = (id: string) => Math.min(budgetOf(id), deadline - Date.now());
  const proof = new ProofLog(env, 'PreToolUse', tool);

  let result: HookResult = outputSilentSuccess();
  try {
    if (route?.primary) {
      const primaryId = route.handlers[0];
      try {
        const primary = route.primary;
        const budget = left(primaryId);
        const r = await withBudget(() => {
          if (proofBreaks(env, primaryId)) throw proofBreakError(primaryId);
          return primary(input, ctx);
        }, budget);
        if (r === TIMED_OUT) {
          // A verdict lost to time fails closed: deny, naming the hook.
          ctx.log(HOOK_NAME, `${primaryId} over its ${budget} ms budget (abandoned, denies)`);
          proof.record(primaryId, 'failed');
          result = {
            continue: true,
            hookSpecificOutput: {
              hookEventName: 'PreToolUse',
              permissionDecision: 'deny',
              permissionDecisionReason: `[orchestkit] hook "${primaryId}" did not finish within its ${budget} ms budget, so it denies.`,
            },
          };
        } else {
          result = r;
          proof.record(primaryId, 'ok');
        }
      } catch (err) {
        proof.record(primaryId, 'failed');
        if (!proofEnabled(env)) throw err;
        ctx.log(HOOK_NAME, `${primaryId} failed (proof mode): ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  } finally {
    for (const [i, observer] of (route?.observers ?? []).entries()) {
      const id = route?.handlers[i + (route.primary ? 1 : 0)] ?? 'observer';
      await isolated(id, observer, input, ctx, env, proof, left(id));
    }
    await isolated('lifecycle/webhook-forwarder', webhookForwarder, input, ctx, env, proof, left('lifecycle/webhook-forwarder'));
  }
  const message = proof.appendTo(result.systemMessage);
  return message === undefined ? result : { ...result, systemMessage: message };
}
